/* Syscall Definition */
long keyctl(int operation, unsigned long arg2,
            unsigned long arg3, unsigned long arg4,
            unsigned long arg5);

/* Common Operations (Defined in <keyutils.h>) */
#define KEYCTL_GET_THREAD_KEYRING  1
#define KEYCTL_ADD                 2
#define KEYCTL_LINK               14

/* Get the calling thread's default keyring ID */
long keyring_id = keyctl(KEYCTL_GET_THREAD_KEYRING);

/* Add a key: (Type, Desc, Value Ptr, Len, Keyring ID) */
char data[] = "my_secret_payload";
long new_key_id = keyctl(KEYCTL_ADD, (unsigned long)"user",
    (unsigned long)"session.data", (unsigned long)data,
    sizeof(data), keyring_id);

/* Link key 1234 to keyring 5678 */
long status = keyctl(KEYCTL_LINK, 1234UL, 5678UL);
